import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'info' | 'danger' | 'default' }
> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'info' },
  over: { label: 'Превышение', tone: 'danger' },
  archived: { label: 'В архиве', tone: 'default' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'over', 'archived'];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Портал самообслуживания', used: 720, quota: 1000, status: 'active' },
  { id: 'p2', name: 'Мобильное приложение для курьеров', used: 1180, quota: 1000, status: 'over' },
  { id: 'p3', name: 'Аналитика продаж', used: 340, quota: 1000, status: 'paused' },
  { id: 'p4', name: 'Биллинг и тарификация', used: 905, quota: 1000, status: 'active' },
  { id: 'p5', name: 'Внутренний поиск по документам', used: 120, quota: 800, status: 'archived' },
  { id: 'p6', name: 'Интеграции с партнёрами', used: 640, quota: 800, status: 'active' },
  { id: 'p7', name: 'Онбординг новых сотрудников', used: 95, quota: 500, status: 'paused' },
  { id: 'p8', name: 'Платформа уведомлений', used: 512, quota: 500, status: 'over' },
  { id: 'p9', name: 'Витрина данных для финансов', used: 260, quota: 600, status: 'active' },
  { id: 'p10', name: 'Легаси-миграция CRM', used: 430, quota: 600, status: 'archived' },
  { id: 'p11', name: 'Каталог товаров', used: 555, quota: 700, status: 'active' },
  { id: 'p12', name: 'Служба поддержки', used: 690, quota: 700, status: 'paused' },
];

const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(STATUS_ORDER);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const visible = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setStatuses((current) =>
      current.includes(status)
        ? current.filter((item) => item !== status)
        : [...current, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(STATUS_ORDER);
    setPage(1);
  };

  return (
    <section
      aria-label="Расход по проектам"
      style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)' }}>Расход по проектам</h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)' }}>
          Показано {filtered.length} из {PROJECTS.length} проектов
        </p>
      </header>

      <div
        role="group"
        aria-label="Фильтр по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {STATUS_ORDER.map((status) => {
          const selected = statuses.includes(status);
          return (
            <JxChip
              key={status}
              active={selected}
              removable={selected}
              onRemove={() => toggleStatus(status)}
              onClick={() => toggleStatus(status)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status);
                }
              }}
              role="button"
              tabIndex={0}
              aria-pressed={selected}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ни один проект не подходит под фильтры"
          message="Все статусы сняты, поэтому показывать нечего. Верните хотя бы один статус или сбросьте фильтры."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {visible.map((project) => {
              const percent = Math.round((project.used / project.quota) * 100);
              const meta = STATUS_META[project.status];
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                    background: 'var(--jx-surface)',
                  }}
                >
                  <JxProgressCircle
                    value={Math.min(percent, 100)}
                    showValue
                    aria-label={`Квота проекта «${project.name}» заполнена на ${percent}%`}
                  />
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '2px', minWidth: 0, flex: 1 }}>
                    <span
                      style={{
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        color: 'var(--jx-text)',
                      }}
                      title={project.name}
                    >
                      {project.name}
                    </span>
                    <span style={{ color: 'var(--jx-text-2)', fontFamily: 'var(--jx-font-mono)' }}>
                      {project.used} / {project.quota} ({percent}%)
                    </span>
                  </div>
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          {pageCount > 1 ? (
            <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
          ) : null}
        </>
      )}
    </section>
  );
}

